function main(csv){
  if(csv==null){return 0}
  let sum=0;
  const lines=csv.split(/\r?\n/);
  for(let line of lines){
    const t=line.trim();
    if(t==='') continue;
    const parts=t.split(',');
    for(let p of parts){
      const s=p.trim();
      if(s==='') continue;
      const v=Number(s);
      if(!Number.isNaN(v)) sum+=v;
    }
  }
  return sum;
}

